const DisplayItems = memo(({ itemsArray }) => {
    const [randomOffsets, setRandomOffsets] = useState([]);
    const elementRef = useRef(null);

    const { scrollYProgress } = useScroll({
        target: elementRef,
        offset: ['start 1', 'end 1'],
    });

    useEffect(() => {
        const generateMasonryOffsets = () => {
            const columnCount = 8;
            const columnWidth = Array(columnCount).fill(0);

            return itemsArray.map((_, index) => {
                const col = index % columnCount;
                const offsetX = columnWidth[col];
                columnWidth[col] = index%2 === 0 ? col+200 : col;

                return {
                    offsetX : 0,
                    offsetY: index%2 !== 0 ? col-400 : col-200,
                };
            });
        };

        setRandomOffsets(generateMasonryOffsets());
    }, [itemsArray]);

    const getGridPosition = (index) => {
        const row = Math.floor(index / 8);
        const col = index % 8;

        return {
            x: col * 0,
            y: index%2 !== 0 ? col+200 : col+100,
        };
    };

    return (
        <div
            ref={elementRef}
            className="relative flex justify-center overflow-hidden -mt-10 w-full px-6 md:px-0 lg:px-14"
            style={{
                height: "130vh",
                WebkitMaskImage: "linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 25%, rgba(0,0,0,1) 75%, rgba(0,0,0,0) 100%)",
                maskImage: "linear-gradient(to bottom, rgba(0,0,0,0) 3%, rgba(0,0,0,1) 25%, rgba(0,0,0,1) 75%, rgba(0,0,0,0) 97%)",
                WebkitMaskRepeat: "no-repeat",
                maskRepeat: "no-repeat",
                WebkitMaskSize: "100% 100%",
                maskSize: "100% 100%",
            }}
        >
            <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-4 xl:grid-cols-6 2xl:grid-cols-8 justify-evenly gap-6 mx-auto py-10 w-full">
                {itemsArray.map((item, index) => {
                    const masonryPosition = randomOffsets[index] || { offsetX: 0, offsetY: 0 };
                    const gridPosition = getGridPosition(index);

                    const translateX = useTransform(
                        scrollYProgress,
                        [0, 1],
                        [Math.max(masonryPosition.offsetX, 0), gridPosition.x]
                    );
                    const translateY = useTransform(
                        scrollYProgress,
                        [0, 1],
                        [Math.max(masonryPosition.offsetY, 30), gridPosition.y]
                    );

                    return (
                        <motion.div
                            key={item.id || index}
                            className="relative flex flex-col items-center justify-center w-36 h-36 md:w-44 mx-auto md:h-44 bg-neutral-800 rounded-lg cursor-pointer shadow-2xl"
                            style={{
                                translateY,
                            }}
                            whileHover={{
                                scale: 1.1,
                                boxShadow: "0px 20px 40px rgba(0, 0, 0, 0.5)",
                            }}
                            transition={{
                                type: "spring",
                                stiffness: 170,
                                damping: 10,
                            }}
                            onClick={() => item.link && window.open(item.link)}
                        >
                            <div className="w-20 h-20 mb-4">
                                {item.img ? (
                                    <img
                                        src={item.img}
                                        alt={item.name}
                                        className="w-full h-full object-contain"
                                    />
                                ) : (
                                    item.svg
                                )}
                            </div>
                            <p className="text-center text-lg font-medium text-gray-200">
                                {item.name}
                            </p>
                        </motion.div>
                    );
                })}
            </div>
        </div>
    );
});